/**
 * Cross-runtime parity for the voxel (3D conduction) engine — the TypeScript half.
 *
 * `crates/thermo-core/tests/voxel_golden_vectors.json` is generated by the Rust
 * engine (`crates/thermo-core/tests/voxel_golden.rs`). This file replays every
 * case through `TsVoxelEngine` and asserts EVERY recorded value with `toBe` /
 * `Object.is` — no tolerance. The kernel uses only + − × ÷ in a fixed order, so
 * there is no libm in play and nothing short of bit equality is acceptable.
 *
 * `[MEASURED 2026-11-20]` Mutation check when this file was written: swapping
 * the accumulation order of the y− and y+ terms in `stepOnce` (algebraically
 * identical) failed this suite on the first stage's temperature array; it was
 * reverted. That is the class of drift this file exists to catch.
 *
 * @file src/__tests__/voxelConductionCrossRuntimeParity.test.ts
 */
import { readFileSync } from "fs";
import { join } from "path";

import { TsVoxelEngine } from "@/lib/cooking/voxelConduction";

interface GoldenStage {
  faces: number[];
  resetPeaks: boolean;
  steps: number;
  stableDt: number;
  dt: number;
  energyJ: number;
  minByMaterial: Array<number | null>;
  maxByMaterial: Array<number | null>;
  temps: number[];
  peaks: number[];
}

interface GoldenCase {
  name: string;
  nx: number;
  ny: number;
  nz: number;
  dx: number;
  dy: number;
  dz: number;
  k: number[];
  rhoC: number[];
  initialC: number;
  initialEnergyJ: number;
  material: number[];
  stages: GoldenStage[];
}

const fixture = JSON.parse(
  readFileSync(join(process.cwd(), "crates/thermo-core/tests/voxel_golden_vectors.json"), "utf8"),
) as { cases: GoldenCase[] };

function exact(actual: number, expected: number | null, what: string): void {
  const want = expected ?? Number.NaN;
  if (!Object.is(actual, want)) {
    throw new Error(`${what}: got ${actual}, fixture has ${want} (Δ ${Math.abs(actual - want)})`);
  }
}

function exactArray(actual: Float64Array, expected: number[], what: string): void {
  expect(actual.length).toBe(expected.length);
  expected.forEach((v, i) => exact(actual[i] ?? Number.NaN, v, `${what}[${i}]`));
}

describe("voxel engine reproduces the Rust golden vectors bit-for-bit", () => {
  it("has the cases the generator promises", () => {
    expect(fixture.cases.map((c) => c.name)).toEqual(["three-material-six-faces", "column-1x9x1"]);
    const sixFaces = fixture.cases[0]?.stages[0]?.faces ?? [];
    expect(sixFaces.filter((_, i) => i % 2 === 0)).toContain(0); // one adiabatic face
    const totalSteps = fixture.cases[0]?.stages.reduce((s, st) => s + st.steps, 0) ?? 0;
    expect(totalSteps).toBeGreaterThanOrEqual(50);
    expect(new Set(fixture.cases[0]?.material).size).toBe(3);
  });

  it.each(fixture.cases.map((c) => [c.name, c] as const))("%s", (_name, gc) => {
    const engine = new TsVoxelEngine({
      nx: gc.nx, ny: gc.ny, nz: gc.nz, dxM: gc.dx, dyM: gc.dy, dzM: gc.dz,
      material: gc.material, k: gc.k, rhoC: gc.rhoC, initialC: gc.initialC,
    });
    exact(engine.energyJ(), gc.initialEnergyJ, "initialEnergyJ");
    gc.stages.forEach((st, s) => {
      engine.setFaces(st.faces);
      if (st.resetPeaks) engine.resetPeaks();
      const stable = engine.stableDt();
      exact(stable, st.stableDt, `stage ${s} stableDt`);
      exact(0.9 * stable, st.dt, `stage ${s} dt`);
      engine.step(st.dt, st.steps);
      exact(engine.energyJ(), st.energyJ, `stage ${s} energyJ`);
      st.minByMaterial.forEach((v, m) => exact(engine.minTempWhere(m), v, `stage ${s} min[${m}]`));
      st.maxByMaterial.forEach((v, m) => exact(engine.maxTempWhere(m), v, `stage ${s} max[${m}]`));
      exactArray(engine.temps(), st.temps, `stage ${s} temps`);
      exactArray(engine.peaks(), st.peaks, `stage ${s} peaks`);
      st.temps.forEach((v, c) => exact(engine.tempAt(c), v, `stage ${s} tempAt(${c})`));
    });
    expect(engine.cellCount).toBe(gc.material.length);
  });
});
